import React from 'react';
import { Users } from 'lucide-react';

const TrafficChart = () => {
  return (
    <div className="bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-2xl p-6 shadow-lg border border-white/30 dark:border-neutral-800/50">
      <h3 className="text-lg font-bold text-neutral-900 dark:text-white mb-6">Trafic des utilisateurs</h3>
      <div className="h-64 flex items-center justify-center rounded-xl bg-gradient-to-br from-neutral-50 to-neutral-100 dark:from-neutral-800 dark:to-neutral-900 border border-neutral-200 dark:border-neutral-700">
        <div className="text-center">
          <Users className="h-12 w-12 text-neutral-400 mx-auto mb-4" />
          <p className="text-neutral-600 dark:text-neutral-400">Analyse du trafic</p>
        </div>
      </div>
    </div>
  );
};

export default TrafficChart;
